/// Checks if the sequence `s` starts with the sequence `p`.
fn starts_with(s: &[char], p: &[char]) -> bool {
    if p.is_empty() {
        return true; // An empty prefix matches any sequence
    }
    if s.len() < p.len() {
        return false; // Sequence is shorter than the prefix
    }
    // Check if the characters match
    s.iter().zip(p.iter()).all(|(sc, pc)| sc == pc)
}

/// Checks if the vector `v` has the prefix `p`.
fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    starts_with(v, p)
}

/// Filters the input sequences `xs` by the given prefix `p`.
fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    xs.into_iter()
        .filter(|seq| has_prefix(seq, &p))
        .collect()
}

fn main() {
    // Example usage
    let sequences = vec![
        vec!['a', 'b', 'c'],
        vec!['a', 'b'],
        vec!['b', 'c'],
        vec!['a', 'c', 'd'],
    ];
    let prefix = vec!['a', 'b'];
    
    let filtered = filter_by_prefix(sequences, prefix);
    
    for seq in filtered {
        println!("{:?}", seq);
    }
}